metric_names={'loans':'Loans per game','negativeScoreRate':'Players with negative scores','allInRate':'Hands involving an all-in','eliminationRate':'Eliminated player-orbits','firstOrbitBelowAnte':'Players ending below the ante','firstOrbitEliminated':'Players eliminated in first orbit','riichiPerHand':'Declarations per hand'}
