table(['Measurement','Result'],[
 ['Loans issued',n(lo['total'])],['Loans per game',f2(lo['loansPerGame']['mean'])],['Games requiring a loan',pct(lo['gamesWithLoans']/r['runs'])],['Players ending with a loan',pct(lo['playersWithLoans']/(4*r['runs']))],['Players with a negative final score',pct(r['negativeScores']/(4*r['runs']))],['Maximum loans held by one player',max(lo['playerLoanDistribution'],key=int)],['Riichi declarations',n(ri['declarations'])],['Declarations per 100 hands',f(100*ri['declarations']/r['hands'])],['Declarations rewarded',n(ri['wins'])],['Conversion of all declarations',ci(ri['conversion'])],['Withdrawals on folding',n(ri['withdrawals'])],['Reward sticks minted',n(ri['minted'])],['Sticks spent on fishing',n(ri['spent'])],['Mean sticks left per table',f(ri['remaining']['mean'])]])
